import{_ as e,r as a,o,c,e as s,a as l,s as u}from"./chunks/framework.CXcwiNg-.js";const h=JSON.parse('{"title":"Скачивание файлов - October CMS - 3.x","titleTemplate":false,"description":"Простое скачивание файлов.","frontmatter":{"subtitle":"Простое скачивание файлов."},"headers":[{"level":2,"title":"Кнопки скачивания","slug":"кнопки-скачивания","link":"#кнопки-скачивания","children":[]},{"level":2,"title":"Ответы для скачивания","slug":"ответы-для-скачивания","link":"#ответы-для-скачивания","children":[]},{"level":2,"title":"Пример использования","slug":"пример-использования","link":"#пример-использования","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}],"relativePath":"3.x/ru/cms/features/downloads.md","filePath":"3.x/ru/cms/features/downloads.md"}'),i={name:"3.x/ru/cms/features/downloads.md"};function k(r,n,d,g,m,f){const t=a("pre-heading"),p=a("post-heading");return o(),c("div",null,[s(t),n[0]||(n[0]=l("h1",null,"Скачивание файлов",-1)),s(p),n[1]||(n[1]=u(`<p>October CMS предоставляет простые возможности для скачивания файлов в ответах. Эта функция является опциональной для AJAX-фреймворка для обеспечения лучшей производительности.</p><h2 id="кнопки-скачивания"><a href="#кнопки-скачивания" class="header-anchor">#</a> Кнопки скачивания</h2><p>Чтобы включить скачивание файлов, добавьте атрибут <code>data-request-download</code> на HTML-тег формы или кнопки. Ниже приведён минимальный пример скачивания файла.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onExport<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-download</span><span class="token punctuation">&gt;</span></span>
    Download
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Если атрибут <code>data-request-download=&quot;...&quot;</code> задан на элементе запроса, имя файла в этом атрибуте будет присвоено загружаемому файлу. Следующий пример создаёт файл с именем <strong>data.csv</strong>.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onExport<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-download</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>data.csv<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Download Document
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Чтобы открыть файл в новом окне браузера, что обычно используется для предварительного просмотра PDF, установите атрибут <code>data-browser-target</code> в значение <code>_blank</code>.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onExport<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-download</span> <span class="token attr-name">data-browser-target</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>_blank<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Open in New Window
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block tip"><p>При использовании атрибута download ответ может быть как скачиванием, так и <a href="./../ajax/update-partials.html">обычным AJAX-обновлением</a>.</p></div><h2 id="ответы-для-скачивания"><a href="#ответы-для-скачивания" class="header-anchor">#</a> Ответы для скачивания</h2><p>Внутри вашего <a href="./../ajax/handlers.html">AJAX-обработчика</a> вы можете вернуть тип ответа <code>Response</code> для <a href="./../../extend/services/response-view.html">скачивания файла</a>, где метод <code>download</code> принимает локальный путь к файлу на диске.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onExport</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">download</span><span class="token punctuation">(</span><span class="token function">base_path</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;app/files/installer.zip&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Чтобы преобразовать строку в ответ для скачивания без записи содержимого на диск, используйте метод <code>streamDownload</code>, который принимает callback-функцию (первый аргумент) и имя файла (второй аргумент).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onExport</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">streamDownload</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">echo</span> <span class="token string single-quoted-string">&#39;CSV Contents...&#39;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;export.csv&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Вы также можете использовать <a href="./../../extend/services/storage.html">сервис хранилища</a> для скачивания файлов из медиатеки или любого хранилища. Используйте фасад <code>Storage</code> и метод <code>disk</code> для указания имени диска (первый аргумент), затем вызовите метод <code>download</code> с именем файла для скачивания (первый аргумент).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onExport</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">disk</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;media&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">download</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;archive.zip&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>При работе с <a href="./../../extend/database/attachments.html">файловыми вложениями модели</a> вы можете вызвать метод <code>download</code> на объекте файла.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onDownload</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// ...</span>

    <span class="token keyword">return</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span><span class="token operator">-&gt;</span><span class="token function">download</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="пример-использования"><a href="#пример-использования" class="header-anchor">#</a> Пример использования</h2><p>Следующий пример показывает CMS-страницу, которую можно использовать для скачивания <a href="./../../extend/database/attachments.html">файлового вложения модели</a> с пользовательским именем файла. Она принимает параметры <code>id</code> и <code>disk_name</code> для валидации файла, а затем возвращает ответ браузеру с пользовательским именем файла из параметра <code>file_name</code> (необязательный).</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token comment">## pages/download-file.htm</span>

<span class="token key attr-name">title</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Download File</span>&quot;</span>
<span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/download-file/:id/:disk_name/:file_name?</span>&quot;</span>
<span class="token key attr-name">layout</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">default</span>&quot;</span>
</code></pre></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$file</span> <span class="token operator">=</span> <span class="token class-name class-name-fully-qualified static-context">System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">param</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$file</span> <span class="token operator">||</span> <span class="token operator">!</span><span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token function">isPublic</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">NotFoundException</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token property">disk_name</span> <span class="token operator">!==</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">param</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;disk_name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">NotFoundException</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token variable">$customFileName</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">param</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file_name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$customFileName</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token property">file_name</span> <span class="token operator">=</span> <span class="token variable">$customFileName</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">return</span> <span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token function">download</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code></code></pre></div></div><p>Вы можете создать ссылку на эту страницу в Twig с помощью следующей разметки, где переменная <code>file</code> является экземпляром <code>System\\Models\\File</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>download-file<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>page<span class="token punctuation">(</span><span class="token punctuation">{</span>
    id<span class="token punctuation">:</span> file<span class="token punctuation">.</span>id<span class="token punctuation">,</span>
    disk_name<span class="token punctuation">:</span> file<span class="token punctuation">.</span>disk_name<span class="token punctuation">,</span>
    file_name<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>my-custom-name.png<span class="token punctuation">&#39;</span></span>
<span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><div class="custom-block tip"><p>Если вы хотите отобразить файл встроенным, например как изображение, вызовите метод <code>$file-&gt;output()</code>.</p></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./../../extend/services/response-view.html">Ответы и представления</a></li></ul></div>`,26))])}const w=e(i,[["render",k]]);export{h as __pageData,w as default};
